  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal or institutional credit for a specific action, achievement, or policy outcome, often highlighting their role, advocacy, or influence in bringing about the result.",
    "clarification": "Credit-claiming is identified when the senator uses language such as 'I secured,' 'I helped,' 'I announced,' 'I authored,' or similar phrasing that directly or indirectly attributes a positive outcome to their efforts. This includes taking credit for legislation, funding, awards, or other tangible benefits that result from their actions. The focus is on the senator's personal or institutional role in achieving the outcome.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states, 'Dorgan authored legislation, which was signed into law, that created the National Center designation,' and 'I am very proud of this program at BSC.' This is a clear example of credit-claiming as he directly attributes the achievement to his legislative efforts."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin take credit for announcing federal funding for firefighters, with Mikulski stating, 'I will continue to fight to provide the federal support they need,' and highlighting her role on the Appropriations Subcommittee that funds the program. This demonstrates their direct involvement and credit for the outcome."
      },
      {
        "document_id": "1827",
        "explanation": "Senator Lugar takes credit for including provisions of his Good Samaritan Hunger Relief Act in the Katrina tax relief package, stating, 'I deeply appreciate Chairman Grassley and Ranking Member Baucus including this important provision.' This shows his direct role in advocating for and achieving the inclusion of his legislation."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when a senator merely discusses, criticizes, or expresses opinions about policies, events, or other entities without attributing a specific positive outcome to their own actions. Statements that focus on general support, opposition, or analysis without linking the senator's efforts to a tangible result do not qualify as credit-claiming. Additionally, commemorative or honorary statements that do not involve the senator taking credit for an action are not considered credit-claiming.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Senator Kennedy introduces legislation and discusses its provisions but does not explicitly take personal credit for any specific achievement or outcome. The focus is on the bill's content and his stance, not on his personal role in securing a result."
      },
      {
        "document_id": "214",
        "explanation": "The text commemorates Pearl Harbor and honors military service but does not involve the senator taking personal credit for any specific action or policy. It is purely a reflective and honorary statement."
      },
      {
